<?php $days=[1=>'Segunda',2=>'Terça',3=>'Quarta',4=>'Quinta',5=>'Sexta',6=>'Sábado',7=>'Domingo'];?>
<div class="section-heading"><div><div class="eyebrow">Agenda 2.0</div><h1>Folgas, férias e intervalos</h1><p class="text-secondary mb-0">Tudo aqui bloqueia automaticamente os horários públicos e internos.</p></div><a class="btn btn-light" href="/schedule/settings">Regras da agenda</a></div>
<div class="row g-4"><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Bloqueio pontual</h2><form method="post" action="/schedule/time-off" class="row g-2"><?=
\App\Core\CSRF::field()?><div class="col-12"><select class="form-select" name="professional_id" required><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-6"><input class="form-control" type="datetime-local" name="starts_at" required></div><div class="col-md-6"><input class="form-control" type="datetime-local" name="ends_at" required></div><div class="col-md-4"><select class="form-select" name="type"><option value="vacation">Férias</option><option value="day_off">Folga</option><option value="meeting">Reunião</option><option value="personal">Pessoal</option><option value="other">Outro</option></select></div><div class="col-md-8"><input class="form-control" name="reason" placeholder="Motivo"></div><div class="col-12"><button class="btn btn-primary">Adicionar bloqueio</button></div></form></div></div></div><div class="col-lg-6"><div class="card h-100"><div class="card-body"><h2 class="h5">Intervalo recorrente</h2><form method="post" action="/schedule/breaks" class="row g-2"><?=
\App\Core\CSRF::field()?><div class="col-12"><select class="form-select" name="professional_id" required><?php foreach($professionals as $p):?><option value="<?=(int)$p['id']?>"><?=htmlspecialchars($p['name'])?></option><?php endforeach;?></select></div><div class="col-md-4"><select class="form-select" name="weekday"><?php foreach($days as $i=>$d):?><option value="<?=$i?>"><?=$d?></option><?php endforeach;?></select></div><div class="col-md-4"><input class="form-control" type="time" name="start_time" value="12:00" required></div><div class="col-md-4"><input class="form-control" type="time" name="end_time" value="13:00" required></div><div class="col-12"><input class="form-control" name="label" value="Almoço" placeholder="Nome do intervalo"></div><div class="col-12"><button class="btn btn-primary">Adicionar intervalo</button></div></form></div></div></div></div>
<div class="row g-4 mt-1"><div class="col-lg-7"><div class="card"><div class="card-header"><strong>Próximos bloqueios</strong></div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Profissional</th><th>Período</th><th>Tipo</th><th></th></tr></thead><tbody><?php foreach($timeOff as $o):?><tr><td><?=htmlspecialchars($o['professional_name'])?></td><td><?=date('d/m/Y H:i',strtotime($o['starts_at']))?> → <?=date('d/m/Y H:i',strtotime($o['ends_at']))?></td><td><?=htmlspecialchars($o['type'])?><small class="d-block text-secondary"><?=htmlspecialchars($o['reason']??'')?></small></td><td><form method="post" action="/schedule/time-off/<?=(int)$o['id']?>/cancel"><?=
\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Remover</button></form></td></tr><?php endforeach;?><?php if(!$timeOff):?><tr><td colspan="4" class="empty-state">Nenhum bloqueio futuro.</td></tr><?php endif;?></tbody></table></div></div></div><div class="col-lg-5"><div class="card"><div class="card-header"><strong>Intervalos semanais</strong></div><div class="table-responsive"><table class="table mb-0"><tbody><?php foreach($breaks as $b):?><tr><td><strong><?=htmlspecialchars($b['professional_name'])?></strong><small class="d-block text-secondary"><?=$days[(int)$b['weekday']]?> · <?=substr($b['start_time'],0,5)?>–<?=substr($b['end_time'],0,5)?></small></td><td class="text-end"><form method="post" action="/schedule/breaks/<?=(int)$b['id']?>/delete"><?=
\App\Core\CSRF::field()?><button class="btn btn-sm btn-outline-danger">Remover</button></form></td></tr><?php endforeach;?><?php if(!$breaks):?><tr><td class="empty-state">Nenhum intervalo.</td></tr><?php endif;?></tbody></table></div></div></div></div>
